import { slack } from adapters
import { scan_web } from plugins
chat = slack()

export movement scan_channel(c: <chat-[:channel]->>) {
  pages = scan_web(url: c.`Name`)
  first = FIRST(pages)
  write chat-[:note]-> { Body ?: first.text }
}

